    public class AlmanacController : MainScenePage
    {
        public override void Display()
        {
            base.Display();
            ui.DisplayPage(AlmanacPageType.Index);
            UpdateEntries();
            if (!Main.MusicManager.IsPlaying(LogicMusicID.choosing))
                Main.MusicManager.Play(LogicMusicID.choosing);
        }
        public void OpenEnemyAlmanac(NamespaceID id)
        {
            ui.DisplayPage(AlmanacPageType.Enemies);
            if (enemyEntries.Contains(id))
            {
                SetActiveEnemyEntry(id);
            }
            else
            {
                SetActiveEnemyEntry(enemyEntries.FirstOrDefault());
            }
        }
        private void Awake()
        {
            propReplacer = new DescriptionPropReplacer(Main);
            ui.OnReturnClick += OnReturnClickCallback;

            ui.OnIndexButtonClick += OnIndexButtonClickCallback;

            ui.OnCommandBlockClick += OnCommandBlockClickCallback;

            ui.OnContraptionEntryClick += OnContraptionEntryClickCallback;
            ui.OnMiscEntryClick += OnMiscEntryClickCallback;
            ui.OnGroupEntryClick += OnGroupEntryClickCallback;
            ui.OnZoomClick += OnZoomClickCallback;

            ui.OnDescriptionIconEnter += OnDescriptionIconEnterCallback;
            ui.OnDescriptionIconExit += OnDescriptionIconExitCallback;
            ui.OnDescriptionIconDown += OnDescriptionIconDownCallback;
            ui.OnDescriptionLinkClick += OnDescriptionLinkClickCallback;
            ui.OnTagIconEnter += OnTagIconEnterCallback;
            ui.OnTagIconExit += OnTagIconExitCallback;
            ui.OnTagIconDown += OnTagIconDownCallback;

            ui.OnZoomReturnClick += OnZoomReturnClickCallback;
            ui.OnZoomPageButtonClick += OnZoomPageButtonClickCallback;
        }
        private void OnReturnClickCallback(bool page)
        {
            UnlockAndHideTooltip();
            if (page)
            {
                ui.DisplayPage(AlmanacPageType.Index);
            }
            else
            {
                Return();
            }
        }
        private void OnIndexButtonClickCallback(IndexAlmanacPage.ButtonType button)
        {
            switch (button)
            {
                case IndexAlmanacPage.ButtonType.ViewContraption:
                    ViewContraptions();
                    break;
                case IndexAlmanacPage.ButtonType.ViewEnemy:
                    ViewEnemies();
                    break;
                case IndexAlmanacPage.ButtonType.ViewArtifact:
                    ViewArtifacts();
                    break;
                case IndexAlmanacPage.ButtonType.ViewMisc:
                    ViewMisc();
                    break;
            }
        }
        private void OnCommandBlockClickCallback(PointerEventData eventData)
        {
            if (eventData.IsMouseButNotLeft())
                return;
            SetActiveContraptionEntry(LogicContraptionID.commandBlock);
            Main.SoundManager.Play2D(LogicSoundID.tap);
        }
        private void OnContraptionEntryClickCallback(int index, PointerEventData data)
        {
            if (data.IsMouseButNotLeft())
                return;
            SetActiveContraptionEntry(contraptionEntries[index]);
            Main.SoundManager.Play2D(LogicSoundID.tap);
        }
        private void OnMiscEntryClickCallback(AlmanacPageType page, int index)
        {
            switch (page)
            {
                case AlmanacPageType.Enemies:
                    SetActiveEnemyEntry(enemyEntries[index]);
                    break;
                case AlmanacPageType.Artifacts:
                    SetActiveArtifactEntry(artifactEntries[index]);
                    break;
            }
            Main.SoundManager.Play2D(LogicSoundID.tap);
        }
        private void OnGroupEntryClickCallback(AlmanacPageType page, int groupIndex, int entryIndex)
        {
            switch (page)
            {
                case AlmanacPageType.Miscs:
                    var group = miscGroups[groupIndex];
                    var entry = group.entries[entryIndex];
                    if (entry != null)
                    {
                        SetActiveMiscEntry(entry);
                    }
                    break;
            }
            Main.SoundManager.Play2D(LogicSoundID.tap);
        }
        #region 缩放
        private void OnZoomClickCallback(AlmanacPageType page)
        {
            if (page != AlmanacPageType.Miscs)
                return;
            var entry = Main.ResourceManager.GetAlmanacMetaEntry(LogicAlmanacCategories.MISC, activeMiscEntryID);

            var picture = entry?.picture;
            var characterID = picture?.character;
            if (NamespaceID.IsValid(characterID))
            {
                ShowCharacterZoom(characterID);
            }
            else
            {
                Sprite? sprite = null;
                if (entry != null)
                {
                    sprite = Main.AlmanacManager.GetEntryPictureSprite(entry);
                }
                if (sprite.Exists())
                {
                    ShowSpriteZoom(sprite, false);
                }
            }
            Main.SoundManager.Play2D(LogicSoundID.tap);
        }
        private void OnZoomReturnClickCallback()
        {
            StopZoom();
        }
        private void OnZoomPageButtonClickCallback(bool next)
        {
            if (zoomPortrait == null)
                return;
            var entry = Main.ResourceManager.GetAlmanacMetaEntry(LogicAlmanacCategories.MISC, activeMiscEntryID);
            var picture = entry?.picture;
            if (picture == null)
                return;
            var characterID = picture.character;
            var characterMeta = Main.ResourceManager.GetCharacterMeta(characterID);
            var offset = next ? 1 : -1;
            if (characterMeta != null)
            {
                var variants = characterMeta.variants;
                if (variants.Count <= 0)
                    return;
                int cycleCount = 0;
                do
                {
                    zoomIndex = MathTool.CycleOffset(zoomIndex, offset, variants.Count);
                    var variant = variants[zoomIndex];
                    if (variant.unlock.IsNullOrMeetsConditions(Main.SaveManager))
                    {
                        var viewData = Main.TalkManager.GetPortraitViewData(variant);
                        zoomPortrait.ChangeVariant(viewData);
                        ui.SetZoomSprite(zoomPortrait.GetSprite());
                        break;
                    }
                    cycleCount++;
                }
                while (cycleCount < variants.Count);
            }
        }
        #endregion

        #region 描述图标
        private void OnTagIconEnterCallback(AlmanacPageType page, int index)
        {
            if (tagTooltipLockedTarget == index)
                return;
            var icon = ui.GetTagIcon(page, index);
            if (!icon.Exists())
                return;
            var tagInfo = GetEntryTagIconInfo(index);
            var viewData = GetTagTooltipViewData(tagInfo.tagID, tagInfo.enumValue);
            Main.Scene.ShowTooltip(new SimpleTooltipSource(almanacCamera, icon, viewData));
            Main.Scene.UpdateTooltip();
            UnlockTooltip();
        }
        private void OnTagIconExitCallback(AlmanacPageType page, int index)
        {
            if (tagTooltipLockedTarget >= 0)
                return;
            Main.Scene.HideTooltip();
        }
        private void OnTagIconDownCallback(AlmanacPageType page, int index)
        {
            if (Main.InputManager.GetActivePointerType() != PointerTypes.TOUCH)
                return;
            LockTooltipEntryTag(tagTooltipLockedTarget == index ? -1 : index);
            Main.SoundManager.Play2D(LogicSoundID.tap);
        }
        private void OnDescriptionIconEnterCallback(AlmanacPageType page, string linkID)
        {
            if (descriptionTagTooltipLockedTarget == linkID)
                return;
            if (!TryParseTagLinkID(linkID, out var index, out var tagID, out var enumValueID))
                return;
            var icon = ui.GetDescriptionIcon(page, index);
            if (!icon.Exists())
                return;
            var viewData = GetTagTooltipViewData(tagID, enumValueID);
            Main.Scene.ShowTooltip(new SimpleTooltipSource(almanacCamera, icon, viewData));
            Main.Scene.UpdateTooltip();
            UnlockTooltip();
        }
        private void OnDescriptionIconExitCallback(AlmanacPageType page, string linkID)
        {
            if (!string.IsNullOrEmpty(descriptionTagTooltipLockedTarget))
                return;
            Main.Scene.HideTooltip();
        }
        private void OnDescriptionIconDownCallback(AlmanacPageType page, string linkID)
        {
            if (Main.InputManager.GetActivePointerType() != PointerTypes.TOUCH)
                return;
            if (descriptionTagTooltipLockedTarget == linkID)
            {
                UnlockTooltip();
            }
            else
            {
                LockTooltipDescription(linkID);
            }
            Main.SoundManager.Play2D(LogicSoundID.tap);
        }
        private void OnDescriptionLinkClickCallback(AlmanacPageType page, string linkID)
        {
            Main.SoundManager.Play2D(LogicSoundID.tap);
            if (!TryParseDescriptionLinkID(linkID, out string type, out var pageID))
                return;
            if (!ValidateDescriptionLink(type, pageID))
                return;
            switch (type)
            {
                case HYPERLINK_TYPE_CONTRAPTIONS:
                    ViewContraptions();
                    SetActiveContraptionEntry(pageID);
                    break;
                case HYPERLINK_TYPE_ENEMIES:
                    ViewEnemies();
                    SetActiveEnemyEntry(pageID);
                    break;
                case HYPERLINK_TYPE_ARTIFACTS:
                    ViewArtifacts();
                    SetActiveArtifactEntry(pageID);
                    break;
                case HYPERLINK_TYPE_MISC:
                    ViewMisc();
                    SetActiveMiscEntry(pageID);
                    break;
            }
        }
        #endregion

        #region 查看某分类
        private void UpdateEntries()
        {
            contraptionEntries.Clear();
            Main.AlmanacManager.GetContraptionPageEntries(contraptionEntries);

            enemyEntries.Clear();
            Main.AlmanacManager.GetEnemyPageEntries(enemyEntries);

            artifactEntries.Clear();
            Main.AlmanacManager.GetArtifactPageEntries(artifactEntries);

            miscGroups.Clear();
            Main.AlmanacManager.GetMiscPageGroups(miscGroups);


            var contraptionViewDatas = contraptionEntries.Select(c => Main.AlmanacManager.GetChoosingBlueprintViewData(c, false)).ToArray();
            var commandBlock = Main.SaveManager.IsCommandBlockUnlocked();
            var commandBlockViewData = Main.AlmanacManager.GetChoosingBlueprintViewData(LogicContraptionID.commandBlock, false);
            ui.SetContraptionEntries(contraptionViewDatas, commandBlock, commandBlockViewData);

            var enemyViewDatas = enemyEntries.Select(c => Main.AlmanacManager.GetEnemyEntryViewData(c)).ToArray();
            ui.SetEnemyEntries(enemyViewDatas);

            var artifactViewDatas = artifactEntries.Select(c => Main.AlmanacManager.GetArtifactEntryViewData(c)).ToArray();
            ui.SetArtifactEntries(artifactViewDatas);
            ui.SetIndexArtifactVisible(artifactEntries.Count > 0);

            var miscViewDatas = miscGroups.Select(c => Main.AlmanacManager.GetMiscGroupViewData(c)).ToArray();
            ui.SetMiscGroups(miscViewDatas);
        }
        private void ViewContraptions()
        {
            var page = Main.UseMobileLayout() ? AlmanacPageType.ContraptionsMobile : AlmanacPageType.ContraptionsStandalone;
            ui.DisplayPage(page);
            SetActiveContraptionEntry(contraptionEntries.FirstOrDefault(e => e != null));
        }
        private void ViewEnemies()
        {
            ui.DisplayPage(AlmanacPageType.Enemies);
            SetActiveEnemyEntry(enemyEntries.FirstOrDefault(e => e != null));
        }
        private void ViewArtifacts()
        {
            ui.DisplayPage(AlmanacPageType.Artifacts);
            SetActiveArtifactEntry(artifactEntries.FirstOrDefault(e => e != null));
        }
        private void ViewMisc()
        {
            ui.DisplayPage(AlmanacPageType.Miscs);
            var entry = miscGroups.FirstOrDefault()?.entries?.FirstOrDefault(e => e != null);
            if (entry != null)
                SetActiveMiscEntry(entry);
        }
        #endregion

        #region 设置当前查看内容
        private void SetActiveContraptionEntry(NamespaceID? contraptionID)
        {
            if (!NamespaceID.IsValid(contraptionID))
                return;
            const string type = LogicAlmanacCategories.CONTRAPTIONS;

            GetEntityAlmanacInfos(contraptionID, type, out var model, out var name, out var description);
            var entry = Main.ResourceManager.GetAlmanacMetaEntry(type, contraptionID);
            if (!string.IsNullOrEmpty(entry?.name))
            {
                name = GetTranslatedString(LogicStrings.GetAlmanacNameContext(type), entry.name);
            }
            if (propReplacer != null && entry != null)
            {
                var context = new AlmanacVariableContext(Main, EngineDefinitionTypes.ENTITY, contraptionID, entry);
                description = propReplacer.Replace(description, context);
            }
            description = ReplaceHyperlinkReferences(description);

            int cost = 0;
            string recharge = string.Empty;
            var definition = Main.Game.GetEntityDefinition(contraptionID);
            if (definition != null)
            {
                cost = definition.GetCost();
                var rechargeID = definition.GetRechargeID();
                var rechargeDefinition = Main.Game.GetRechargeDefinition(rechargeID);
                if (rechargeDefinition != null)
                {
                    recharge = GetTranslatedString(LogicStrings.CONTEXT_RECHARGE_TIME, rechargeDefinition.GetName());
                }
            }
            var costText = GetTranslatedString(LogicStrings.CONTEXT_ALMANAC, COST_LABEL, cost);
            var rechargeText = GetTranslatedString(LogicStrings.CONTEXT_ALMANAC, RECHARGE_LABEL, recharge);

            var page = Main.UseMobileLayout() ? AlmanacPageType.ContraptionsMobile : AlmanacPageType.ContraptionsStandalone;
            UpdateEntryTags(page, type, contraptionID);

            var iconInfos = GetDescriptionTagIconInfos(description);
            var replacements = iconInfos.Select(i => i.replacement).ToArray();
            var iconStacks = iconInfos.Select(i => i.viewData).ToArray();
            var finalDesc = ReplaceText(description, replacements);

            var viewData = new ModelBuilder(model, almanacCamera);
            ui.SetActiveContraptionEntry(viewData, name, finalDesc, costText, rechargeText);
            ui.UpdateContraptionDescriptionIcons(iconStacks);
            UnlockAndHideTooltip();
        }
        private void SetActiveEnemyEntry(NamespaceID? enemyID)
        {
            if (!NamespaceID.IsValid(enemyID))
                return;
            const string type = LogicAlmanacCategories.ENEMIES;
            var entry = Main.ResourceManager.GetAlmanacMetaEntry(type, enemyID);
            if (entry == null)
                return;

            activeEnemyEntryID = enemyID;
            GetEntityAlmanacInfos(enemyID, type, out var model, out var name, out var description);
            if (!string.IsNullOrEmpty(entry.name))
            {
                name = GetTranslatedString(LogicStrings.GetAlmanacNameContext(type), entry.name);
            }
            if (propReplacer != null)
            {
                var context = new AlmanacVariableContext(Main, EngineDefinitionTypes.ENTITY, enemyID, entry);
                description = propReplacer.Replace(description, context);
            }
            description = ReplaceHyperlinkReferences(description);

            var encounterCondition = entry.encounterUnlock;
            bool encountered = (encounterCondition != null && encounterCondition.MeetsConditions(Main.SaveManager)) || Main.SaveManager.IsEnemyEncountered(enemyID);
            if (encountered)
            {
                UpdateEntryTags(AlmanacPageType.Enemies, type, enemyID);
            }
            else
            {
                name = Main.LanguageManager._p(LogicStrings.CONTEXT_ENTITY_NAME, LogicStrings.UNKNOWN_ENTITY_NAME);
                description = Main.LanguageManager._p(LogicStrings.CONTEXT_ALMANAC, LogicStrings.NOT_ENCOUNTERED_YET);

                ClearEntryTags(AlmanacPageType.Enemies);
            }

            var iconInfos = GetDescriptionTagIconInfos(description);
            var replacements = iconInfos.Select(i => i.replacement).ToArray();
            var iconStacks = iconInfos.Select(i => i.viewData).ToArray();
            var finalDesc = ReplaceText(description, replacements);

            var viewData = new ModelBuilder(model, almanacCamera);
            ui.SetActiveEnemyEntry(viewData, name, finalDesc);
            ui.UpdateEnemyDescriptionIcons(iconStacks);
            UnlockAndHideTooltip();
        }
        private void SetActiveArtifactEntry(NamespaceID? artifactID)
        {
            if (!NamespaceID.IsValid(artifactID))
                return;
            const string type = LogicAlmanacCategories.ARTIFACTS;
            var entry = Main.ResourceManager.GetAlmanacMetaEntry(type, artifactID);
            if (entry == null)
                return;


            activeArtifactEntryID = artifactID;
            GetArtifactAlmanacInfos(artifactID, type, out var sprite, out var name, out var description);
            if (propReplacer != null)
            {
                var context = new AlmanacVariableContext(Main, LogicDefinitionTypes.ARTIFACT, artifactID, entry);
                description = propReplacer.Replace(description, context);
            }
            description = ReplaceHyperlinkReferences(description);

            Color color = Color.white;
            bool unlocked = Main.SaveManager.IsArtifactUnlocked(artifactID);
            if (unlocked)
            {
                UpdateEntryTags(AlmanacPageType.Artifacts, type, artifactID);
            }
            else
            {
                color = Color.black;
                name = Main.LanguageManager._p(LogicStrings.CONTEXT_ARTIFACT_NAME, LogicStrings.UNKNOWN_ARTIFACT_NAME);
                description = Main.LanguageManager._p(LogicStrings.CONTEXT_ALMANAC, LogicStrings.ALMANAC_UNKNOWN);

                ClearEntryTags(AlmanacPageType.Artifacts);
            }

            var iconInfos = GetDescriptionTagIconInfos(description);
            var replacements = iconInfos.Select(i => i.replacement).ToArray();
            var iconStacks = iconInfos.Select(i => i.viewData).ToArray();
            var finalDesc = ReplaceText(description, replacements);

            ui.SetActiveArtifactEntry(sprite, color, name, finalDesc);
            ui.UpdateArtifactDescriptionIcons(iconStacks);
            UnlockAndHideTooltip();
        }
        private void SetActiveMiscEntry(NamespaceID miscID)
        {
            var entry = Main.ResourceManager.GetAlmanacMetaEntry(LogicAlmanacCategories.MISC, miscID);
            if (entry == null)
                return;
            activeMiscEntryID = miscID;
            var name = GetTranslatedString(LogicStrings.GetAlmanacNameContext(LogicAlmanacCategories.MISC), entry.name);

            var descContext = LogicStrings.GetAlmanacDescriptionContext(LogicAlmanacCategories.MISC);
            var header = GetTranslatedString(descContext, entry.header);
            header = $"<color=#00007F>{header}</color>";
            var properties = GetTranslatedString(descContext, entry.properties);

            var flavorKeys = entry.GetValidFlavors(Main.SaveManager);
            var flavors = flavorKeys.Select(f => GetTranslatedString(descContext, f));
            var flavor = string.Join("\n\n", flavors);

            var strings = new string[] { header, properties, flavor }.Where(s => !string.IsNullOrEmpty(s));
            var description = string.Join("\n\n", strings);
            if (propReplacer != null)
            {
                var context = new AlmanacVariableContext(Main, EngineDefinitionTypes.ENTITY, miscID, entry);
                description = propReplacer.Replace(description, context);
            }
            description = ReplaceHyperlinkReferences(description);

            var picture = entry.picture;

            UpdateEntryTags(AlmanacPageType.Miscs, LogicAlmanacCategories.MISC, miscID);

            var iconInfos = GetDescriptionTagIconInfos(description);
            var replacements = iconInfos.Select(i => i.replacement).ToArray();
            var iconStacks = iconInfos.Select(i => i.viewData).ToArray();
            var finalDesc = ReplaceText(description, replacements);

            if (picture != null)
            {
                var modelID = picture.model;
                if (NamespaceID.IsValid(modelID) && Main.ResourceManager.GetModelMeta(modelID) is ModelMeta modelMeta)
                {
                    var viewData = new ModelBuilder(modelID, almanacCamera);
                    ui.SetActiveMiscEntry(viewData, name, finalDesc);
                }
                else
                {
                    Sprite? sprite = Main.AlmanacManager.GetEntryPictureSprite(entry);
                    var spriteSized = entry.pictureFixedSize;
                    var zoom = entry.pictureZoom;

                    ui.SetActiveMiscEntry(sprite, name, finalDesc, spriteSized, zoom);
                }
            }
            ui.UpdateMiscDescriptionIcons(iconStacks);
            UnlockAndHideTooltip();
        }
        private void GetEntityAlmanacInfos(NamespaceID entityID, string almanacCategory, out NamespaceID? model, out string name, out string description)
        {
            model = null;
            name = string.Empty;
            description = string.Empty;
            var definition = Main.Game.GetEntityDefinition(entityID);
            if (definition == null)
                return;
            name = Main.ResourceManager.GetEntityName(entityID);
            description = GetAlmanacDescription(entityID, almanacCategory);

            model = definition.GetModelID();
        }
        private void GetArtifactAlmanacInfos(NamespaceID artifactID, string almanacCategory, out Sprite? sprite, out string name, out string description)
        {
            sprite = null;
            name = string.Empty;
            description = string.Empty;
            if (!NamespaceID.IsValid(artifactID))
                return;
            name = Main.ResourceManager.GetArtifactName(artifactID);
            description = GetAlmanacDescription(artifactID, almanacCategory);


            var definition = Main.Game.GetArtifactDefinition(artifactID);
            if (definition == null)
                return;
            var spriteReference = definition.GetSpriteReference();
            if (spriteReference == null)
                return;
            sprite = Main.GetFinalSprite(spriteReference);
        }
        private string GetAlmanacDescription(NamespaceID almanacID, string almanacCategory)
        {
            if (!NamespaceID.IsValid(almanacID))
                return string.Empty;
            var almanacMeta = Main.ResourceManager.GetAlmanacMetaEntry(almanacCategory, almanacID);
            if (almanacMeta == null)
            {
                return string.Empty;
            }
            else
            {
                var context = LogicStrings.GetAlmanacDescriptionContext(almanacCategory);
                var header = GetTranslatedString(context, almanacMeta.header);
                header = $"<color=#00007F>{header}</color>";
                var properties = GetTranslatedString(context, almanacMeta.properties);
                var flavorKeys = almanacMeta.GetValidFlavors(Main.SaveManager);
                var flavors = flavorKeys.Select(f => GetTranslatedString(context, f));
                var flavor = string.Join("\n\n", flavors);
                var strings = new string[] { header, properties, flavor }.Where(s => !string.IsNullOrEmpty(s));
                return string.Join("\n\n", strings);
            }
        }
        #endregion

        #region Description Tag
        private bool TryParseTagLinkID(string linkID, out int index, [NotNullWhen(true)] out NamespaceID? tagID, out string enumValue)
        {
            index = -1;
            tagID = null;
            enumValue = string.Empty;
            var indexStart = linkID.IndexOf('[');
            var indexEnd = linkID.IndexOf(']');
            if (indexStart < 0 || indexEnd < 0)
            {
                return false;
            }
            var indexStr = linkID.Substring(indexStart + 1, indexEnd - indexStart - 1);
            if (!ParseHelper.TryParseInt(indexStr, out index))
            {
                return false;
            }

            var afterIndex = linkID.Substring(indexEnd + 1);
            var ampIndex = afterIndex.IndexOf('&');
            string tagIDStr;
            if (ampIndex < 0)
            {
                tagIDStr = afterIndex;
            }
            else
            {
                tagIDStr = afterIndex.Substring(0, ampIndex);
                enumValue = afterIndex.Substring(ampIndex + 1);
            }
            var defaultNsp = Main.BuiltinNamespace;
            return NamespaceID.TryParse(tagIDStr, defaultNsp, out tagID);
        }
        private string GetLinkIDByTag(int index, string tagID)
        {
            return $"[{index}]{tagID}";
        }
        private string GetLinkIDByEnumTag(int index, string tagID, string enumID)
        {
            return $"[{index}]{tagID}&{enumID}";
        }
        private TooltipContent GetTagTooltipViewData(NamespaceID tagID, string enumValue)
        {
            AlmanacTagMeta? tagMeta = Main.ResourceManager.GetAlmanacTagMeta(tagID);
            if (tagMeta == null)
                return default;
            string name = string.Empty;
            string desc = string.Empty;
            if (NamespaceID.IsValid(tagMeta.enumType))
            {
                var defaultNsp = Main.BuiltinNamespace;
                var enumMeta = Main.ResourceManager.GetAlmanacTagEnumMeta(tagMeta.enumType);
                var enumValueMeta = enumMeta?.FindValueByString(enumValue, defaultNsp);
                if (enumValueMeta != null)
                {
                    var tagName = Main.LanguageManager._p(LogicStrings.CONTEXT_ALMANAC_TAG_NAME, tagMeta.name);
                    var enumValueName = Main.LanguageManager._p(LogicStrings.CONTEXT_ALMANAC_TAG_ENUM_NAME, enumValueMeta.name);
                    name = Main.LanguageManager._p(LogicStrings.CONTEXT_ALMANAC, TAG_ENUM_TEMPLATE, tagName, enumValueName);
                    desc = Main.LanguageManager._p(LogicStrings.CONTEXT_ALMANAC_TAG_ENUM_DESCRIPTION, enumValueMeta.description);
                    return new TooltipContent()
                    {
                        name = name,
                        description = desc,
                    };
                }
            }
            name = Main.LanguageManager._p(LogicStrings.CONTEXT_ALMANAC_TAG_NAME, tagMeta.name);
            desc = Main.LanguageManager._p(LogicStrings.CONTEXT_ALMANAC_TAG_DESCRIPTION, tagMeta.description);
            return new TooltipContent()
            {
                name = name,
                description = desc,
            };
        }
        private DescriptionTagIconInfo[] GetDescriptionTagIconInfos(string text)
        {
            List<DescriptionTagIconInfo> infos = new List<DescriptionTagIconInfo>();

            string pattern = @"<tag +id ?= ?""([\w:]*)""( +enum ?= ?""([\w:]*)"")? */>";
            var matches = Regex.Matches(text, pattern);
            var defaultNsp = Main.BuiltinNamespace;
            for (int i = 0; i < matches.Count; i++)
            {
                var match = matches[i];
                string linkID;
                if (match.Groups.Count < 2)
                    continue;
                var tagIDStr = match.Groups[1].Value;
                if (!NamespaceID.TryParse(tagIDStr, defaultNsp, out var tagID))
                    continue;
                AlmanacTagMeta? tagMeta = Main.ResourceManager.GetAlmanacTagMeta(tagID);
                if (tagMeta == null)
                    continue;
                string enumValue = string.Empty;
                if (match.Groups.Count > 3 && match.Groups[3].Success)
                {
                    enumValue = match.Groups[3].Value;
                }
                GetTagMetaViewProperties(tagMeta, enumValue, out var iconSpriteRef, out var backgroundSpriteRef, out var backgroundColor, out var markSpriteRef);
                if (!string.IsNullOrEmpty(enumValue))
                {
                    linkID = GetLinkIDByEnumTag(i, tagIDStr, enumValue);
                }
                else
                {
                    linkID = GetLinkIDByTag(i, tagIDStr);
                }

                var iconSprite = Main.GetFinalSprite(iconSpriteRef);
                var backgroundSprite = Main.GetFinalSprite(backgroundSpriteRef);
                var markSprite = Main.GetFinalSprite(markSpriteRef);
                var size = new Vector2(32, 32);
                if (backgroundSprite.Exists())
                {
                    size = backgroundSprite.rect.size;
                }


                // 存储替换信息
                string rep = string.Empty;
                rep += $"<link=\"{linkID}\">";
                rep += $"<space={descriptionTagSpacing}>";
                rep += $"<sprite=\"tag_icon_placeholder\" index=0>";
                rep += $"<space={descriptionTagSpacing}>";
                rep += $"</link>";
                var replacement = new ReplacementInfo()
                {
                    startIndex = match.Index,
                    length = match.Length,
                    text = rep
                };
                var iconViewdata = new AlmanacTagIconViewData()
                {
                    background = new AlmanacTagIconLayerViewData() { sprite = backgroundSprite, tint = backgroundColor },
                    main = new AlmanacTagIconLayerViewData() { sprite = iconSprite, tint = Color.white },
                    mark = new AlmanacTagIconLayerViewData() { sprite = markSprite, tint = Color.white }
                };
                var viewData = new AlmanacDescriptionTagViewData()
                {
                    linkID = linkID,
                    icon = iconViewdata,
                    size = size,
                };
                infos.Add(new DescriptionTagIconInfo()
                {
                    replacement = replacement,
                    viewData = viewData
                });
            }
            return infos.ToArray();
        }
        private static string ReplaceText(string text, ReplacementInfo[] replacements)
        {
            StringBuilder sb = new StringBuilder(text);
            for (int i = replacements.Length - 1; i >= 0; i--)
            {
                var replacement = replacements[i];
                sb.Remove(replacement.startIndex, replacement.length);
                sb.Insert(replacement.startIndex, replacement.text);
            }
            return sb.ToString();
        }
        #endregion

        #region Entry Tag
        private AlmanacEntryTagInfo[] GetEntryTags(string category, NamespaceID id)
        {
            List<AlmanacEntryTagInfo> list = new List<AlmanacEntryTagInfo>();
            var almanacEntry = Main.ResourceManager.GetAlmanacMetaEntry(category, id);
            if (almanacEntry != null)
            {
                var param = new LogicCallbacks.GetAlmanacEntryTagsParams(category, id, almanacEntry.tagSourceEntity, list);
                Global.Game.RunCallbackFiltered(LogicCallbacks.GET_ALMANAC_ENTRY_TAGS, param, category);

                list.AddRange(almanacEntry.tags);
            }
            list.Sort(CompareEntryTagInfo);
            return list.Distinct().ToArray();
        }
        private int CompareEntryTagInfo(AlmanacEntryTagInfo a, AlmanacEntryTagInfo b)
        {
            var metaA = Main.ResourceManager.GetAlmanacTagMeta(a.tagID);
            var metaB = Main.ResourceManager.GetAlmanacTagMeta(b.tagID);
            var priorityA = metaA?.priority ?? 0;
            var priorityB = metaB?.priority ?? 0;
            return priorityA.CompareTo(priorityB);
        }
        private void UpdateEntryTags(AlmanacPageType page, string category, NamespaceID id)
        {
            var tags = GetEntryTags(category, id);

            currentTags.Clear();
            currentTags.AddRange(tags);

            var viewDatas = currentTags.Select(t => GetTagIconViewData(t)).ToArray();
            ui.UpdateTagIcons(page, viewDatas);
        }
        private void ClearEntryTags(AlmanacPageType page)
        {
            currentTags.Clear();
            ui.UpdateTagIcons(page, Array.Empty<AlmanacTagIconViewData>());
        }
        private AlmanacEntryTagInfo GetEntryTagIconInfo(int index)
        {
            return currentTags[index];
        }
        private AlmanacTagIconViewData GetTagIconViewData(AlmanacEntryTagInfo info)
        {
            var tagID = info.tagID;
            AlmanacTagMeta? tagMeta = Main.ResourceManager.GetAlmanacTagMeta(tagID);
            if (tagMeta == null)
                return default;
            GetTagMetaViewProperties(tagMeta, info.enumValue, out var iconSpriteRef, out var backgroundSpriteRef, out var backgroundColor, out var markSpriteRef);

            var iconSprite = Main.GetFinalSprite(iconSpriteRef);
            var backgroundSprite = Main.GetFinalSprite(backgroundSpriteRef);
            var markSprite = Main.GetFinalSprite(markSpriteRef);

            return new AlmanacTagIconViewData()
            {
                background = new AlmanacTagIconLayerViewData() { sprite = backgroundSprite, tint = backgroundColor },
                main = new AlmanacTagIconLayerViewData() { sprite = iconSprite, tint = Color.white },
                mark = new AlmanacTagIconLayerViewData() { sprite = markSprite, tint = Color.white },
            };
        }
        private void GetTagMetaViewProperties(AlmanacTagMeta tagMeta, string enumValue, out SpriteReference? iconSpriteRef, out SpriteReference? backgroundSpriteRef, out Color backgroundColor, out SpriteReference? markSpriteRef)
        {
            var defaultNsp = Main.BuiltinNamespace;
            iconSpriteRef = tagMeta.iconSprite;
            backgroundSpriteRef = tagMeta.backgroundSprite;
            backgroundColor = tagMeta.backgroundColor;
            markSpriteRef = tagMeta.markSprite;
            if (NamespaceID.IsValid(tagMeta.enumType))
            {
                AlmanacTagEnumMeta? tagEnumMeta = Main.ResourceManager.GetAlmanacTagEnumMeta(tagMeta.enumType);
                AlmanacTagEnumValueMeta? valueMeta = tagEnumMeta?.FindValueByString(enumValue, defaultNsp);
                if (valueMeta != null)
                {
                    iconSpriteRef = valueMeta.iconSprite;
                    backgroundColor = valueMeta.backgroundColor;
                }
            }
        }
        #endregion

        #region Description Link
        private string ReplaceHyperlinkReferences(string description)
        {
            return hyperlinkRegex.Replace(description, m =>
            {
                var linkID = m.Groups[1].Value;
                var text = m.Groups[2].Value;
                if (!TryParseDescriptionLinkID(linkID, out var type, out var pageID))
                    return m.Value;
                if (!ValidateDescriptionLink(type, pageID))
                    return text;
                return $"<color=blue><u><link={linkID}>{m.Groups[2].Value}</link></u></color>";
            });
        }
        private bool TryParseDescriptionLinkID(string linkID, out string type, [NotNullWhen(true)] out NamespaceID? pageID)
        {
            type = string.Empty;
            pageID = null;
            var typeStart = linkID.IndexOf('[');
            var typeEnd = linkID.IndexOf(']');
            if (typeStart < 0 || typeEnd < 0)
            {
                return false;
            }
            type = linkID.Substring(typeStart + 1, typeEnd - typeStart - 1);

            var afterIndex = linkID.Substring(typeEnd + 1);
            string tagIDStr = afterIndex;
            var defaultNsp = Main.BuiltinNamespace;
            return NamespaceID.TryParse(tagIDStr, defaultNsp, out pageID);
        }
        private bool ValidateDescriptionLink(string type, NamespaceID? pageID)
        {
            switch (type)
            {
                case HYPERLINK_TYPE_CONTRAPTIONS:
                    if (pageID == LogicContraptionID.commandBlock)
                    {
                        if (!Main.SaveManager.IsCommandBlockUnlocked())
                            return false;
                    }
                    else
                    {
                        if (!contraptionEntries.Contains(pageID))
                            return false;
                    }
                    break;
                case HYPERLINK_TYPE_ENEMIES:
                    if (!enemyEntries.Contains(pageID))
                        return false;
                    break;
                case HYPERLINK_TYPE_ARTIFACTS:
                    if (!artifactEntries.Contains(pageID))
                        return false;
                    break;
                case HYPERLINK_TYPE_MISC:
                    if (!miscGroups.Any(g => g.entries.Contains(pageID)))
                        return false;
                    break;
            }
            return true;
        }
        #endregion

        #region 放大镜
        private void ShowCharacterZoom(NamespaceID characterID)
        {
            bool canSwitchPage = false;
            var characterMeta = Main.ResourceManager.GetCharacterMeta(characterID);
            if (characterMeta == null)
                return;
            var unlockedVariants = characterMeta.variants.Where(v => v.unlock.IsNullOrMeetsConditions(Main.SaveManager));
            int variantCount = unlockedVariants.Count();
            if (variantCount <= 0)
                return;
            if (variantCount > 1)
            {
                canSwitchPage = true;
            }

            var variant = unlockedVariants.First();
            zoomPortrait = Main.TalkManager.CreateCharacterPortrait(variant);
            ShowSpriteZoom(zoomPortrait.GetSprite(), canSwitchPage);
        }
        private void ShowSpriteZoom(Sprite sprite, bool canSwitchPage)
        {
            var textKey = Main.InputManager.GetActivePointerType() == PointerTypes.TOUCH ? ZOOM_HINT_TOUCH : ZOOM_HINT_MOUSE;
            var hintText = Main.LanguageManager._p(LogicStrings.CONTEXT_ALMANAC, textKey);
            ui.SetZoomHintText(hintText);
            ui.SetZoomPageButtonsActive(canSwitchPage);
            ui.SetZoomSprite(sprite);
            ui.StartZoom();
            zoomIndex = 0;
        }
        private void StopZoom()
        {
            ui.StopZoom();
            if (zoomPortrait != null)
            {
                zoomPortrait.Dispose();
                zoomPortrait = null;
            }
        }
        #endregion

        private void LockTooltipEntryTag(int entryTagIndex)
        {
            tagTooltipLockedTarget = entryTagIndex;
            descriptionTagTooltipLockedTarget = string.Empty;
