        private List<NamespaceID?> enemyEntries = new List<NamespaceID?>();
        private List<NamespaceID?> artifactEntries = new List<NamespaceID?>();
        private List<AlmanacEntryGroup> miscGroups = new List<AlmanacEntryGroup>();
